import { useEffect, useMemo } from 'react'
import { shortDate, today } from './dates'
import { PRIVATE_TIKTOK } from './private'
import { SAMPLE_TIKTOK } from './sampleTikTok'
import { update, useAppState } from './store'
import { daysBetweenISO, emptySnapshot, mergeSnapshots, newestDataDate, normalizeCsv, exportedAtFromName, parseExport, type TikTokSnapshot } from './tiktok'
import type { AppState, FollowerSnapshot } from './types'

/**
 * Base TikTok data: the private vault (generated by `pnpm tiktok:ingest`, reloaded by Vite in dev),
 * else fictional sample data for the sample creator, else nothing.
 */
export const vaultSnapshot = (sample: boolean): TikTokSnapshot => PRIVATE_TIKTOK ?? (sample ? SAMPLE_TIKTOK : emptySnapshot())

export function useTikTok(): TikTokSnapshot {
  const s = useAppState()
  const sample = s.profile.sample
  return useMemo(() => (s.tiktokImport ? mergeSnapshots(vaultSnapshot(sample), s.tiktokImport) : vaultSnapshot(sample)), [s.tiktokImport, sample])
}

export const STALE_AFTER_DAYS = 7

export function dataAge(tk: TikTokSnapshot, on = today()) {
  const newest = newestDataDate(tk)
  if (!newest) return null
  const days = daysBetweenISO(newest, on)
  return { newest, days, stale: days > STALE_AFTER_DAYS }
}

/** Manual snapshots plus the TikTok export's daily follower history (verified evidence). */
export function combinedSnapshots(manual: FollowerSnapshot[], tk: TikTokSnapshot): FollowerSnapshot[] {
  if (!tk.followers.length) return manual
  const exportDates = new Set(tk.followers.map((f) => f.date))
  const fromExport: FollowerSnapshot[] = tk.followers.map((f) => {
    const sample = f.file.startsWith('sample-data')
    return {
      id: `TT-${f.date}`,
      platform: 'tiktok',
      date: f.date,
      count: f.count,
      source: sample ? 'Sample data (fictional)' : `TikTok Studio export · ${shortDate(f.at.slice(0, 10))}`,
      verified: !sample,
    }
  })
  // Export history replaces demo TikTok snapshots and any manual entry for the same day.
  const kept = manual.filter((m) => m.platform !== 'tiktok' || (!m.demo && !exportDates.has(m.date)))
  return [...kept, ...fromExport]
}

export function useFollowerSnapshots() {
  const s = useAppState()
  const tk = useTikTok()
  return useMemo(() => combinedSnapshots(s.snapshots, tk), [s.snapshots, tk])
}

/** Once real follower history exists, the illustrative demo baseline is removed. */
export function useDropDemoTikTokBaseline() {
  const s = useAppState()
  const tk = useTikTok()
  const hasDemo = s.snapshots.some((x) => x.demo && x.platform === 'tiktok')
  useEffect(() => {
    if (hasDemo && tk.followers.length)
      update((st: AppState) => ({ ...st, snapshots: st.snapshots.filter((x) => !(x.demo && x.platform === 'tiktok')) }))
  }, [hasDemo, tk.followers.length])
}

const hex = (buf: ArrayBuffer) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('')
const sha256 = async (text: string) => hex(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text)))

export interface ImportResult {
  added: string[]
  duplicates: string[]
  rejected: string[]
}

/** Browser-side import. Kept in this browser only; the vault stays the source of record. */
export async function importTikTokFiles(files: File[], current: TikTokSnapshot | null, base: TikTokSnapshot): Promise<{ snapshot: TikTokSnapshot | null; result: ImportResult }> {
  const result: ImportResult = { added: [], duplicates: [], rejected: [] }
  const known = new Set([...base.exports, ...(current?.exports ?? [])].map((e) => e.sha256))
  const parts: TikTokSnapshot[] = current ? [current] : []
  for (const file of files) {
    const text = await file.text()
    const [raw, norm] = await Promise.all([sha256(text), sha256(normalizeCsv(text))])
    if (known.has(raw) || known.has(norm)) {
      result.duplicates.push(file.name)
      continue
    }
    const stamped = exportedAtFromName(file.name)
    const exportedAt = stamped ?? new Date(file.lastModified).toISOString().replace(/\.\d{3}Z$/, 'Z')
    const parsed = parseExport(file.name, text, norm, exportedAt, stamped ? 'filename' : 'mtime')
    if ('error' in parsed) {
      result.rejected.push(file.name)
      continue
    }
    known.add(norm)
    parts.push(parsed.snapshot)
    result.added.push(file.name)
  }
  return { snapshot: parts.length ? { ...mergeSnapshots(...parts), generatedAt: new Date().toISOString() } : current ?? emptySnapshot(), result }
}
